import FreeCAD

# Open the precondition file
doc = FreeCAD.open("/home/user/Precondition_Unnamed.FCStd")

# Check if there's a Cam workbench we can load
import os
freecad_path = os.path.dirname(FreeCAD.__file__)
print(f"FreeCAD path: {freecad_path}")

# Look for CAM-related files
cam_paths = []
for root, dirs, files in os.walk(freecad_path):
    for d in dirs:
        if 'cam' in d.lower():
            cam_paths.append(os.path.join(root, d))
    for f in files:
        if 'cam' in f.lower() and (f.endswith('.py') or f.endswith('.so')):
            cam_paths.append(os.path.join(root, f))

print(f"\nFound CAM-related paths:")
for p in cam_paths[:20]:
    print(f"  {p}")

FreeCAD.closeDocument(doc.Name)
EOF"}

